mapper.select:
SELECT

FROM ccds_battle_group
WHERE station_id = #{stationId}
  AND name = #{name}
LIMIT 1

mapper.update:
UPDATE ccds_battle_group
SET sort_no = #{sortNo},
    gmt_modified = #{gmtModified}
WHERE id = #{id}

mapper.delete:
DELETE FROM ccds_battle_group
WHERE id = #{id}
  AND is_fixed = 0

DELETE FROM ccds_battle_group
WHERE station_id = #{stationId}
  AND is_fixed = 0
